import sys, numpy as np
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); o=r.get_obs(depth=True,video='none'); c='egocentric_mirrored_camera';
def w(u,v):
 d=o.last_depth[c]; a=d[max(0,v-2):v+3,max(0,u-2):u+3]; a=a[a>0]; z=np.median(a); K=np.array(o.meta['cameras'][c]['intrinsic_cv']); E=np.array(o.meta['cameras'][c]['extrinsic_cv']); p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]); T=np.eye(4); T[:3]=E; return (np.linalg.inv(T)@p)[:3]
pts={'drill handle center':(395,180),'drill body center':(450,185),'drill chuck':(454,145),'clamp handle A':(310,320),'clamp handle B':(392,320),'clamp hinge':(350,270),'grey opening center':(170,263),'grey interior left/back':(110,205),'grey interior right/back':(225,205),'grey interior left/front':(110,320),'grey interior right/front':(225,320),'grey rim':(175,160)}
for n,p in pts.items(): print(n,p, np.round(w(*p),3))
# IK test: down pose targets
q=np.array(o.meta['proprio']['now'][:7]);
for xyz in [[.415,-.055,.20],[.415,-.055,.015],[.57,-.36,.22],[.57,-.36,.14],[.67,-.16,.20],[.67,-.16,.015]]:
  res=r.ik({'tcp': [*xyz,0.,-.70710678,.70710678,0.]},seed=q)
  print('IK',xyz,res.get('ok'),np.round(res.get('error',{}).get('tcp',{}).get('pos_m',-1),4),np.round(res.get('q',[]),3))
